      ro: "La Condamine este al doilea cel mai vechi cartier din Monaco, după Monaco-Ville. Numele său înseamnă „teren cultivabil” la poalele unui castel, reflectând rolul său istoric ca centru agricol și comercial al principatului. Cartierul este centrat în jurul Portului Hercule, singurul port cu ape adânci din Monaco. Acest port nu este doar un centru pentru iahturi de lux, ci și locația celebrului Monaco Yacht Show. Una dintre atracțiile sale principale este Piața Condamine (Marché de la Condamine), o piață tradițională vibrantă deschisă în 1880, care atrage atât localnici, cât și turiști cu produse locale și specialități culinare. Rue Princesse Caroline, o zonă pietonală animată, oferă numeroase magazine și restaurante. La Condamine este, de asemenea, semnificativ pentru fanii sporturilor cu motor, deoarece linia de start/sosire a Marelui Premiu de Formula 1 al Monaco este situată chiar lângă port, creând un fundal dramatic pentru cursă.",
      en: "La Condamine is the second oldest district in Monaco, after Monaco-Ville. Its name means 'cultivable land' at the foot of a castle, reflecting its historic role as the agricultural and commercial hub of the principality. The district is centered around Port Hercules, Monaco's only deep-water port. This harbour is not only a hub for luxury yachts but also the venue for the world-renowned Monaco Yacht Show. One of its main attractions is the Condamine Market (Marché de la Condamine), a vibrant traditional market opened in 1880 that attracts both locals and tourists with local produce and culinary specialties. The Rue Princesse Caroline, a bustling pedestrianized street, offers numerous shops and restaurants. La Condamine is also significant for motorsport fans, as the start/finish line of the Formula 1 Monaco Grand Prix is located right by the port, providing a dramatic backdrop for the race.",
