      pt: "La Condamine é o bairro portuário central do Mónaco e inclui o famoso Port Hercule. É um dos bairros mais antigos e serve como um importante centro de negócios com um mercado animado. Aqui situam-se as retas de partida e de chegada da pista de Fórmula 1. O distrito liga a histórica Monaco-Ville à moderna Monte-Carlo.",
      fr: "La Condamine est le quartier portuaire central de Monaco et comprend le célèbre Port Hercule. C'est l'un des plus anciens quartiers et il sert de centre d'affaires important avec une place de marché animée. Les lignes de départ et d'arrivée du circuit de Formule 1 s'y trouvent. Le quartier relie l'historique Monaco-Ville au moderne Monte-Carlo.",
