      en: ["Work on the gardens began in 1816 during a period of famine.", "It was the first public garden established in the Principality.", "A statue of Prince Albert I stands overlooking the sea.", "The gardens are located between the Oceanographic Museum and the Cathedral.", "Home to rare species such as Aleppo pines and holm oaks.", "Numerous archaeological artifacts were discovered on this site."],
      es: ["La construcción comenzó en 1816 durante una época de hambruna.", "Fue el primer jardín público del principado.", "Una estatua del Príncipe Alberto I mira hacia el mar.", "Los jardines se encuentran entre el Museo Oceanográfico y la Catedral.", "Crecen especies raras como pinos de Alepo y encinas.", "Se han descubierto numerosos hallazgos arqueológicos en este recinto."],
      pt: ["A construção foi iniciada em 1816 durante um período de fome.", "Foi o primeiro jardim público do principado.", "Uma estátua do Príncipe Alberto I contempla o mar.", "Os jardins situam-se entre o Museu Oceanográfico e a Catedral.", "Aqui crescem espécies raras como pinheiros-de-Alepo e azinheiras.", "Inúmeras descobertas arqueológicas foram feitas neste local."],
      fr: ["L'aménagement a débuté en 1816 lors d'une période de famine.", "Il s'agit du premier jardin public de la principauté.", "Une statue du Prince Albert Ier regarde vers la mer.", "Les jardins se trouvent entre le Musée océanographique et la Cathédrale.", "Des espèces rares comme les pins d'Alep et les chênes verts y poussent.", "De nombreuses découvertes archéologiques ont été faites sur ce site."],
