      hu: ["A társasági élet középpontja", "Itt található a Hôtel de Paris és a Café de Paris", "A közösségi élet központja", "Gyakran tele luxusautókkal"],
      ro: ["Locul unde să vezi și să fii văzut", "Hôtel de Paris și Café de Paris se află aici", "Centrul vieții sociale", "Adesea plină de mașini de lux"],
      en: ["The place to see and be seen", "Hôtel de Paris and Café de Paris are located here", "Center of social life", "Often filled with luxury cars"],
      es: ["Lugar para ver y ser visto", "El Hôtel de Paris y el Café de Paris se encuentran aquí", "Centro de la vida social", "A menudo llena de coches de lujo"],
      pt: ["Local para ver e ser visto", "O Hôtel de Paris e o Café de Paris situam-se aqui", "Centro da vida social", "Frequentemente cheia de carros de luxo"],
      fr: ["Lieu pour voir et être vu", "L'Hôtel de Paris et le Café de Paris s'y trouvent", "Centre de la vie sociale", "Souvent remplie de voitures de luxe"],
